interface AsyncRemoveDataItemsByFilterSignature {
  /**
   * Removes all data items matching a filter. Runs asynchronously.
   *
   *
   * This method selects all items that match the specified filter and removes each one.
   * Unlike [Bulk Remove Data Items](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/bulk-remove-data-items), you don't need to specify individual item IDs. Instead, items are selected by filter.
   *
   * The operation runs asynchronously and returns a job ID for tracking status.
   * Call [Get Async Job Status](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/get-async-job-status) with the returned job ID to poll for status.
   *
   * An empty `filter` removes all items in the collection.
   *
   * > **Notes:**
   * > - The number of affected items is not bounded.
   * > - If any item fails to be removed, the async job stops and its status becomes `FAILED`. Some items may already have been removed before the failure.
   * > - Calling this method triggers the [Data Item Deleted](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/data-item-deleted) event for each removed item.
   * > - Job records are retained for 30 days. After that, querying the job ID returns `NOT_FOUND`.
   */
  (
    options?: NonNullablePaths<
      AsyncRemoveDataItemsByFilterOptions,
      `dataCollectionId`,
      2
    >
  ): Promise<
    NonNullablePaths<AsyncRemoveDataItemsByFilterResponse, `jobId`, 2>
  >;
}

export function getAsyncJobStatus(
  httpClient: HttpClient
): GetAsyncJobStatusSignature {
  return (jobId: string) =>
    universalGetAsyncJobStatus(
      jobId,
      // @ts-ignore
      { httpClient }
    );
}

interface GetAsyncJobStatusSignature {
  /**
   * Retrieves the status of an async job started by [Async Patch Data Items By Filter](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/async-patch-data-items-by-filter)
   * or [Async Remove Data Items By Filter](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/async-remove-data-items-by-filter).
   *
   * Poll this endpoint until the status reaches a terminal state: `SUCCEEDED` or `FAILED`.
   * Job records are retained for 30 days after reaching a terminal state.
   * Querying an expired or unknown `jobId` returns `NOT_FOUND`.
   *
   * When status is `FAILED`, use `successCount` to understand how far the job progressed,
   * then re-run the originating async operation with a modified filter that excludes already-processed items.
   * @param - Job ID returned from an async operation, such as
   * [Async Patch Data Items By Filter](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/async-patch-data-items-by-filter)
   * or [Async Remove Data Items By Filter](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/async-remove-data-items-by-filter).
   */
  (jobId: string): Promise<
    NonNullablePaths<GetAsyncJobStatusResponse, `status` | `successCount`, 2>
  >;
}

