interface PublishDataItemDraftSignature {
  /**
   * Publishes a pending draft of a data item.
   *
   *
   * This method replaces the published item's data with the draft's content. On success, the draft is deleted.
   *
   * Pass the **published** collection ID as `dataCollectionId` (for example, `articles`).
   *
   * To author a brand-new draft, call [Insert Data Item](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/insert-data-item) with `dataCollectionId` set to your collection's drafts shadow (for example, `articles__drafts` when the published collection ID is `articles`). Edit the draft via [Update Data Item](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/update-data-item) or [Patch Data Item](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/patch-data-item) against the same drafts shadow collection ID.
   *
   * To retract a published item back to draft state, call [Unpublish Data Item](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/unpublish-data-item).
   *
   * > **Notes:**
   * > - Returns `NOT_FOUND` if no pending draft exists for the supplied `dataItemId`.
   * > - Calling this method triggers domain events on both collections: a [Data Item Created](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/data-item-created) or [Data Item Updated](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/data-item-updated) event on the published collection, and a [Data Item Deleted](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/data-item-deleted) event on the drafts shadow collection.
   */
  (
    options: NonNullablePaths<
      PublishDataItemDraftOptions,
      `dataCollectionId` | `dataItemId`,
      2
    >
  ): Promise<
    NonNullablePaths<
      PublishDataItemDraftResponse,
      `dataItem._id` | `dataItem.dataCollectionId`,
      3
    >
  >;
}

