export function registerV2(httpClient: HttpClient): RegisterV2Signature {
  return (loginId: LoginId, options?: RegisterV2Options) =>
    universalRegisterV2(
      loginId,
      options,
      // @ts-ignore
      { httpClient }
    );
}

interface RegisterV2Signature {
  /**
   * Registers a new member.
   *
   * Typically, after a successful registration, you generate and use member tokens for the
   * registered member so that subsequent API calls are called as part of a member session.
   * Use the `sessionToken` in the response to [get the site member's access and refresh tokens](https://dev.wix.com/docs/go-headless/coding/rest-api/visitors-and-members/handle-members-with-custom-login#get-the-site-members-access-and-refresh-tokens).
   *
   * If the email used to register the member already exists as a contact email, the registering
   * member need to verify the email address using a code that is sent to the address.
   * @param - Identifier of the registering member.
   */
  (loginId: LoginId, options?: RegisterV2Options): Promise<
    NonNullablePaths<
      StateMachineResponse,
      | `state`
      | `identity.connections`
      | `identity.connections.${number}.idpConnection.idpConnectionId`
      | `identity.connections.${number}.idpConnection.idpUserId`
      | `identity.connections.${number}.authenticatorConnection.authenticatorConnectionId`
      | `identity.connections.${number}.authenticatorConnection.reEnrollmentRequired`
      | `identity.identityProfile.emails`
      | `identity.identityProfile.phones`
      | `identity.identityProfile.labels`
      | `identity.identityProfile.privacyStatus`
      | `identity.identityProfile.customFields`
      | `identity.identityProfile.customFields.${number}.name`
      | `identity.identityProfile.customFields.${number}.value.strValue`
      | `identity.identityProfile.customFields.${number}.value.numValue`
      | `identity.identityProfile.customFields.${number}.value.boolValue`
      | `identity.identityProfile.secondaryEmails`
      | `identity.identityProfile.secondaryEmails.${number}.email`
      | `identity.identityProfile.secondaryEmails.${number}.tag`
      | `identity.identityProfile.phonesV2`
      | `identity.identityProfile.phonesV2.${number}.phone`
      | `identity.identityProfile.phonesV2.${number}.tag`
      | `identity.identityProfile.addresses`
      | `identity.identityProfile.addresses.${number}.tag`
      | `identity.email.address`
      | `identity.email.isVerified`
      | `identity.status.name`
      | `identity.status.reasons`
      | `identity.factors`
      | `identity.factors.${number}.factorId`
      | `identity.factors.${number}.type`
      | `identity.factors.${number}.status`,
      7
    > & {
      __applicationErrorsType?: RegisterV2ApplicationErrors;
      __validationErrorsType?: RegisterV2ValidationErrors;
    }
  >;
}

