export const __metadata = { PACKAGE_NAME: '@wix/identity' };

export function getSignOnPolicy(
  httpClient: HttpClient
): GetSignOnPolicySignature {
  return () =>
    universalGetSignOnPolicy(
      // @ts-ignore
      { httpClient }
    );
}

interface GetSignOnPolicySignature {
  /**
   * Retrieves the calling site's sign-on policy.
   *
   * The request takes no parameters. The site is resolved from the request context.
   *
   * A site that has never updated its policy still gets a successful response,
   * with each requirement set to its default of `false`.
   *
   * The response currently contains `requireOwnerApproval` and `requireEmailVerification`.
   *
   * This method needs a minimum amount of time left on the request deadline,
   * 200 ms by default. A call that arrives with less time remaining fails with
   * `INSUFFICIENT_DEADLINE_BUDGET`.
   */
  (): Promise<
    NonNullablePaths<
      GetSignOnPolicyResponse,
      | `signOnPolicy.requireOwnerApproval`
      | `signOnPolicy.requireEmailVerification`,
      3
    > & {
      __applicationErrorsType?: GetSignOnPolicyApplicationErrors;
    }
  >;
}

export function updateSignOnPolicy(
  httpClient: HttpClient
): UpdateSignOnPolicySignature {
  return (signOnPolicy: SignOnPolicy) =>
    universalUpdateSignOnPolicy(
      signOnPolicy,
      // @ts-ignore
      { httpClient }
    );
}

interface UpdateSignOnPolicySignature {
  /**
   * Updates the calling site's sign-on policy.
   *
   * Partial updates are supported. Specify only the requirements you want to change,
   * and the rest keep their current values.
   *
   * Changing the policy affects members who sign up from that point on.
   * Existing members aren't re-evaluated, so turning on `requireOwnerApproval`
   * doesn't move already-active members back to pending.
   *
   * Fails with `NOT_FOUND` when the site doesn't have a sign-on policy yet,
   * and with `INVALID_ARGUMENT` when the request contains an unsupported value.
   * @param - Sign-on policy to update. Can be partial, and omitted requirements keep their current values.
   * @returns Updated sign-on policy.
   */
  (signOnPolicy: SignOnPolicy): Promise<
    NonNullablePaths<
      SignOnPolicy,
      `requireOwnerApproval` | `requireEmailVerification`,
      2
    > & {
      __applicationErrorsType?: UpdateSignOnPolicyApplicationErrors;
    }
  >;
}

export const onSignOnPolicyUpdated = /*#__PURE__*/ EventDefinition(
  'wix.iam.signon.v1.sign_on_policy_updated',
  true,
  (event: SignOnPolicyUpdatedEnvelope) =>
    renameKeysFromRESTResponseToSDKResponse(
      transformPaths(event, [
        {
          transformFn: transformRESTTimestampToSDKTimestamp,
          paths: [
            { path: 'entity.createdDate' },
            { path: 'entity.updatedDate' },
            { path: 'metadata.eventTime' },
          ],
        },
      ])
    )
)<SignOnPolicyUpdatedEnvelope>();

